from __future__ import annotations

import sys
import unittest
from pathlib import Path
from types import ModuleType
from types import SimpleNamespace
from unittest.mock import patch

import numpy as np


PACKAGE_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PACKAGE_ROOT))

# The message package is generated by colcon and may not be importable in a
# plain source-tree pytest run. This test exercises only the controller's
# scheduling helper, so a minimal fallback import stub is sufficient.
try:
    import rebotarm_msgs.action  # noqa: F401
except ModuleNotFoundError:
    rebotarm_msgs = ModuleType("rebotarm_msgs")
    rebotarm_msgs_action = ModuleType("rebotarm_msgs.action")
    rebotarm_msgs_action.MoveToPose = object
    rebotarm_msgs.action = rebotarm_msgs_action
    sys.modules["rebotarm_msgs"] = rebotarm_msgs
    sys.modules["rebotarm_msgs.action"] = rebotarm_msgs_action

from rebotarmcontroller.ros_actions import ArmActions  # noqa: E402


class TrajectoryInterpolationTests(unittest.TestCase):
    def test_segment_updates_targets_between_waypoints(self) -> None:
        action = ArmActions.__new__(ArmActions)
        action._hardware = SimpleNamespace(state_machine="TRAJ_RUNNING")
        observed = []
        action._set_endpos_target = lambda names, target: observed.append(
            (list(names), np.array(target, copy=True))
        )
        goal_handle = SimpleNamespace(
            is_cancel_requested=False,
            request=SimpleNamespace(
                trajectory=SimpleNamespace(joint_names=["joint1"])
            ),
        )

        with (
            patch(
                "rebotarmcontroller.ros_actions.time.monotonic",
                side_effect=[100.0, 100.25, 100.5, 100.75, 101.0],
            ),
            patch("rebotarmcontroller.ros_actions.time.sleep"),
        ):
            completed = action._follow_trajectory_segment(
                goal_handle,
                trajectory_start=100.0,
                segment_start_time=0.0,
                segment_end_time=1.0,
                segment_start=np.array([0.0]),
                segment_end=np.array([1.0]),
                result=SimpleNamespace(),
            )

        self.assertTrue(completed)
        self.assertEqual([entry[0] for entry in observed], [["joint1"]] * 5)
        np.testing.assert_allclose(
            [entry[1][0] for entry in observed],
            [0.0, 0.25, 0.5, 0.75, 1.0],
        )


if __name__ == "__main__":
    unittest.main()
